import{_ as c,C as s,o as a,c as h,a3 as t,b as o,w as l,a as d,E as r,a4 as n}from"./chunks/framework.DACwFHq9.js";const P=JSON.parse('{"title":"AIO Hub 自营订阅服务调查","description":"","frontmatter":{},"headers":[],"relativePath":"design/可能性碎片/aio-subscription-service-investigation.md","filePath":"design/可能性碎片/aio-subscription-service-investigation.md","lastUpdated":1786004113000}'),p={name:"design/可能性碎片/aio-subscription-service-investigation.md"};function u(b,e,g,A,k,m){const i=s("Mermaid");return a(),h("div",null,[e[2]||(e[2]=t(`<h1 id="aio-hub-自营订阅服务调查" tabindex="-1">AIO Hub 自营订阅服务调查 <a class="header-anchor" href="#aio-hub-自营订阅服务调查" aria-label="Permalink to &quot;AIO Hub 自营订阅服务调查&quot;">​</a></h1><blockquote><p>状态：可能性调查；已补充低成本云服务估算与客户端基础建设缺口，不代表进入实施排期</p><p>最后更新：2026-08-06</p><p>范围：AIO Hub 产品本体、可比产品的云服务演进、适合 AIO 的订阅对象、云服务成本、客户端基础建设与落地顺序等构想</p><p>纠偏说明：旧版错误地把 AIO 当成“功能很多的 Chat 客户端”，因此把官方模型订阅放在了产品中心。该前提不成立，本文已删除旧结论并重新调查。</p></blockquote><h2 id="_1-先定义-aio-hub-是什么" tabindex="-1">1. 先定义 AIO Hub 是什么 <a class="header-anchor" href="#_1-先定义-aio-hub-是什么" aria-label="Permalink to &quot;1. 先定义 AIO Hub 是什么&quot;">​</a></h2><h3 id="_1-1-aio-不是-chat-客户端" tabindex="-1">1.1 AIO 不是 Chat 客户端 <a class="header-anchor" href="#_1-1-aio-不是-chat-客户端" aria-label="Permalink to &quot;1.1 AIO 不是 Chat 客户端&quot;">​</a></h3><p>Chat 是 AIO 当前最复杂、最成熟的旗舰工作区，但不是 AIO 的产品边界。</p><p>截至 2026-08-06，桌面端 <code>src/tools/</code> 下有 47 个 registry 文件，其中约 36 个同时提供服务注册，约 18 个明确向 Agent 暴露可调用方法。它们覆盖：</p><ul><li>Chat、Agent、上下文、Recall、Knowledge、Embedding 与媒体生成；</li><li>OCR、转写、FFmpeg、网页蒸馏、Git 分析、文件和目录操作；</li><li>资产、用户档案、世界书、画布和任务管理；</li><li>JS、Native、Sidecar 插件；</li><li>Agent Skill、工具调用、VCP 远程工具桥接和分布式节点。</li></ul><p>如果把 AIO 看成 Chat 客户端，就无法解释为什么它需要：</p><ul><li>工具 UI 自动注册和统一工作区；</li><li><code>ToolRegistry</code>、统一执行器和 Agent Callable 方法；</li><li>JS / Native / Sidecar 三种插件运行时；</li><li>应用级资产库、Knowledge、Recall 和 User Profile；</li><li>组件/工具分离窗口和跨窗口状态同步；</li><li>VCP 分布式节点以及桌面作为 Companion Backend 的构想。</li></ul><h3 id="_1-2-aio-的产品公式" tabindex="-1">1.2 AIO 的产品公式 <a class="header-anchor" href="#_1-2-aio-的产品公式" aria-label="Permalink to &quot;1.2 AIO 的产品公式&quot;">​</a></h3><p>更准确的定义是：</p><blockquote><p><strong>AIO Hub 是一个本地优先、可扩展、同时面向人和 Agent 的个人能力枢纽。</strong></p><p>它把复杂 AI、内容、文件、媒体和系统能力放进统一工作区；用户可以直接操作，Agent 可以通过同一服务边界调用，插件和 Skill 可以继续扩展，桌面还可以作为用户自己的私有执行后端被其他设备或外部 Agent 使用。</p></blockquote><p>可以拆成五层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作区 Shell</span></span>
<span class="line"><span>  多标签、分离窗口、自由布局、统一设置与主题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>能力 Runtime</span></span>
<span class="line"><span>  Tool Registry、Executor、异步任务、审批与权限</span></span>
<span class="line"><span></span></span>
<span class="line"><span>扩展系统</span></span>
<span class="line"><span>  内置工具、JS/Native/Sidecar 插件、Agent Skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>共享本地数据底座</span></span>
<span class="line"><span>  Asset、Knowledge、Recall、User Profile、会话与项目</span></span>
<span class="line"><span></span></span>
<span class="line"><span>智能与连接层</span></span>
<span class="line"><span>  LLM/Agent 编排、VCP 节点、移动 Companion、外部调用</span></span></code></pre></div><p>Chat、媒体生成、Web Canvas、Knowledge 工作台等，是这个能力枢纽上的不同复杂应用，而不是所有工具都依附于 Chat。</p><h3 id="_1-3-hub-的真正含义" tabindex="-1">1.3 “Hub”的真正含义 <a class="header-anchor" href="#_1-3-hub-的真正含义" aria-label="Permalink to &quot;1.3 “Hub”的真正含义&quot;">​</a></h3><p>AIO 的关键不是“有很多工具”，而是同一能力可以拥有多个入口：</p>`,17)),(a(),o(n,null,{default:l(()=>[r(i,{id:"mermaid-118",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20H%5B%22%E4%BA%BA%E7%9B%B4%E6%8E%A5%E6%93%8D%E4%BD%9C%20UI%22%5D%20--%3E%20R%5B%22AIO%20Capability%20Runtime%22%5D%0A%20%20%20%20A%5B%22AIO%20Agent%22%5D%20--%3E%20R%0A%20%20%20%20P%5B%22%E6%8F%92%E4%BB%B6%20%2F%20Skill%22%5D%20--%3E%20R%0A%20%20%20%20V%5B%22%E5%A4%96%E9%83%A8%20VCP%20Agent%22%5D%20--%3E%20R%0A%20%20%20%20M%5B%22%E7%A7%BB%E5%8A%A8%20Companion%22%5D%20--%3E%20R%0A%20%20%20%20R%20--%3E%20T%5B%22%E5%B7%A5%E5%85%B7%E4%B8%8E%E5%B7%A5%E4%BD%9C%E5%8C%BA%22%5D%0A%20%20%20%20R%20--%3E%20D%5B%22%E6%9C%AC%E5%9C%B0%E8%B5%84%E4%BA%A7%20%2F%20%E7%9F%A5%E8%AF%86%20%2F%20%E6%96%87%E4%BB%B6%20%2F%20%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20%20%20R%20--%3E%20L%5B%22%E7%94%A8%E6%88%B7%E9%80%89%E6%8B%A9%E7%9A%84%E6%A8%A1%E5%9E%8B%E4%B8%8E%E5%A4%96%E9%83%A8%E6%9C%8D%E5%8A%A1%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t(`<p>因此，AIO 的商业服务应该增强这个 Hub 的连接、分发、托管和协作能力，而不是只给 Chat 换一个默认模型 Provider。</p><h2 id="_2-为什么-chat-客户端会长出自己的模型订阅" tabindex="-1">2. 为什么 Chat 客户端会长出自己的模型订阅 <a class="header-anchor" href="#_2-为什么-chat-客户端会长出自己的模型订阅" aria-label="Permalink to &quot;2. 为什么 Chat 客户端会长出自己的模型订阅&quot;">​</a></h2><p>Chatbox、LobeHub 等产品的主价值链基本是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入 → 调用模型 → 显示结果</span></span></code></pre></div><p>模型调用是产品每次使用都无法绕开的生产资料。因此它们增加官方模型套餐可以同时解决：</p><ul><li>用户不会申请和充值 API；</li><li>模型选择和协议复杂；</li><li>移动端配置麻烦；</li><li>产品需要持续收入；</li><li>官方可以控制默认体验和可用性。</li></ul><p>对它们来说，“官方模型服务”接近基础设施。</p><p>AIO 的价值链则是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户或 Agent 表达意图</span></span>
<span class="line"><span>  → 调用本地/远程能力</span></span>
<span class="line"><span>  → 处理文件、资产、知识、媒体、系统或模型</span></span>
<span class="line"><span>  → 形成可继续编辑、执行、复用的结果</span></span></code></pre></div><p>LLM 是重要的调度器和生产能力，但不是所有流程的必经上游。目录清理、FFmpeg、OCR、本地检索、文件处理、画板、Git 分析和插件运行可以完全不经过官方模型。</p><p>所以，直接复制 Chatbox 的订阅会产生三个问题：</p><ol><li>只改善一部分 AI 功能的开箱体验，没有增强整个 Hub；</li><li>把产品重心从“用户自己的能力环境”推向“官方云模型入口”；</li><li>收入高度依赖 Token 差价，但 AIO 的真正差异化并不在模型采购。</li></ol><p>结论不是“不做官方模型”，而是：</p><blockquote><p><strong>官方模型应该是 AIO 云能力中的一个 Provider，不应该成为 AIO 订阅的定义。</strong></p></blockquote><h2 id="_3-更准确的可比产品" tabindex="-1">3. 更准确的可比产品 <a class="header-anchor" href="#_3-更准确的可比产品" aria-label="Permalink to &quot;3. 更准确的可比产品&quot;">​</a></h2><p>AIO 没有一个完全同类产品。更合适的比较方法是按产品结构寻找参照。</p><h3 id="_3-1-raycast-工具-shell、扩展生态与-ai-控制层" tabindex="-1">3.1 Raycast：工具 Shell、扩展生态与 AI 控制层 <a class="header-anchor" href="#_3-1-raycast-工具-shell、扩展生态与-ai-控制层" aria-label="Permalink to &quot;3.1 Raycast：工具 Shell、扩展生态与 AI 控制层&quot;">​</a></h3><p>Raycast 最接近 AIO 的“统一入口 + 扩展 + AI 调工具”结构：</p><ul><li>扩展是产品能力的基本构件；</li><li>Store 负责发现、安装和自动更新；</li><li>普通命令可以直接由人执行；</li><li>扩展声明 AI Tools 后，Raycast AI 可以在 Chat、Quick AI 和 Root Search 中调用它；</li><li>Pro 订阅承载 AI、跨设备和团队价值。</li></ul><p>对 AIO 的启示：</p><ul><li>AI 订阅的价值不只是回答问题，而是让 AI 操作整个扩展能力网络；</li><li>官方 Store、更新、权限和团队私有扩展属于 Hub 级服务；</li><li>订阅可以解锁云端 AI 控制层，但本地工具仍可独立工作。</li></ul><h3 id="_3-2-home-assistant-cloud-本地-hub-外围的付费连接层" tabindex="-1">3.2 Home Assistant Cloud：本地 Hub 外围的付费连接层 <a class="header-anchor" href="#_3-2-home-assistant-cloud-本地-hub-外围的付费连接层" aria-label="Permalink to &quot;3.2 Home Assistant Cloud：本地 Hub 外围的付费连接层&quot;">​</a></h3><p>Home Assistant 的核心和用户数据保持本地，Nabu Casa 的订阅主要提供：</p><ul><li>无需配置端口和证书的安全远程访问；</li><li>云备份；</li><li>语音助手云连接；</li><li>Webhook 和更方便的云集成；</li><li>通过订阅反哺开源项目。</li></ul><p>这与 AIO 的桌面 Companion Backend 构想高度对应。AIO 桌面拥有模型密钥、工具、插件、资产和任务；付费云层不必接管它们，只需提供安全的设备身份、连接、备份和通知。</p><h3 id="_3-3-obsidian-local-first-核心与可选官方服务" tabindex="-1">3.3 Obsidian：Local-first 核心与可选官方服务 <a class="header-anchor" href="#_3-3-obsidian-local-first-核心与可选官方服务" aria-label="Permalink to &quot;3.3 Obsidian：Local-first 核心与可选官方服务&quot;">​</a></h3><p>Obsidian 的本地知识库可免费使用，官方按需销售 Sync 和 Publish：</p><ul><li>不订阅也能继续使用本地文件；</li><li>Sync 解决设备、版本历史和端到端加密；</li><li>Publish 把本地内容选择性发布为公共服务；</li><li>付费对象是跨边界能力，而不是本地编辑器本身。</li></ul><p>对 AIO 的启示：</p><ul><li>本地数据所有权与官方订阅可以共存；</li><li>“备份/同步”和“发布/分享”应分成不同授权边界；</li><li>订阅失效不能让用户失去本地数据或核心能力。</li></ul><p>但 AIO 不应直接复制 Obsidian 的全量多端同步。现有 Companion 构想已经明确：桌面应作为权威后端，移动端通过受控协议访问，避免把模型密钥、插件、资产和复杂任务做成多主复制。</p><h3 id="_3-4-msty-本地-ai-工作台向控制中心和团队服务演进" tabindex="-1">3.4 Msty：本地 AI 工作台向控制中心和团队服务演进 <a class="header-anchor" href="#_3-4-msty-本地-ai-工作台向控制中心和团队服务演进" aria-label="Permalink to &quot;3.4 Msty：本地 AI 工作台向控制中心和团队服务演进&quot;">​</a></h3><p>Msty 当前产品族包含：</p><ul><li>Studio：本地/在线模型、知识、工具、MCP 和 AI 工作区；</li><li>Go：移动访问；</li><li>Nexus：集中管理模型、凭据、预设、权限和 OpenAI-compatible 访问；</li><li>Stack：面向组织的自托管部署与治理。</li></ul><p>这说明当产品从 Chat 成长为能力工作台后，付费重心会转向：</p><ul><li>中央 Provider 和凭据管理；</li><li>团队共享的智能体、预设和知识；</li><li>访问控制、审计和多应用接入；</li><li>私有部署与支持。</li></ul><p>这比单纯的模型月卡更接近 AIO 后期可能形成的产品结构。</p><h3 id="_3-5-n8n-dify-本地执行引擎与托管控制面" tabindex="-1">3.5 n8n / Dify：本地执行引擎与托管控制面 <a class="header-anchor" href="#_3-5-n8n-dify-本地执行引擎与托管控制面" aria-label="Permalink to &quot;3.5 n8n / Dify：本地执行引擎与托管控制面&quot;">​</a></h3><p>n8n 和 Dify 都保留自托管路径，同时销售官方 Cloud 或商业自托管版本：</p><ul><li>用户付费购买免运维、团队协作、权限、监控、支持和更高资源；</li><li>价格通常按工作流执行、消息、团队规模或资源，而不是只按 Token；</li><li>可变 AI 用量和稳定的软件/托管权益被分开计量。</li></ul><p>对 AIO 的启示：如果未来出现远程任务、共享工作流、团队节点和托管执行，应该按“节点、任务、存储、并发和席位”计价，而不是全部换算成模型积分。</p><h2 id="_4-aio-真正适合卖什么" tabindex="-1">4. AIO 真正适合卖什么 <a class="header-anchor" href="#_4-aio-真正适合卖什么" aria-label="Permalink to &quot;4. AIO 真正适合卖什么&quot;">​</a></h2><h3 id="_4-1-推荐的产品分层" tabindex="-1">4.1 推荐的产品分层 <a class="header-anchor" href="#_4-1-推荐的产品分层" aria-label="Permalink to &quot;4.1 推荐的产品分层&quot;">​</a></h3><p>建议把官方商业服务作为 <code>AIO Cloud</code> 总称，下面分成三类性质完全不同的产品。</p><h4 id="aio-link-连接用户自己的-hub" tabindex="-1">AIO Link：连接用户自己的 Hub <a class="header-anchor" href="#aio-link-连接用户自己的-hub" aria-label="Permalink to &quot;AIO Link：连接用户自己的 Hub&quot;">​</a></h4><p>这是最符合 AIO 本体、也最类似 Nabu Casa 的订阅。</p><p>可包含：</p><ul><li>AIO 账号和设备身份；</li><li>桌面—移动端安全配对；</li><li>官方 Relay / 信令 / Endpoint 协调，免去 VPN、FRP 和端口配置；</li><li>后台任务完成、审批请求和异常的推送通知；</li><li>桌面在线状态和设备管理；</li><li>端到端加密的配置与元数据备份；</li><li>受控的临时资产传输；</li><li>远程访问审计和设备撤销。</li></ul><p>关键原则：</p><ul><li>桌面仍是业务真源和执行端；</li><li>AIO Cloud 只处理连接和必要状态，不默认复制完整业务数据库；</li><li>Relay 尽量传输端到端加密的数据；</li><li>不把桌面内部 Tauri command、文件路径或任意代理直接暴露到公网。</li></ul><h4 id="aio-capability-cloud-官方托管能力" tabindex="-1">AIO Capability Cloud：官方托管能力 <a class="header-anchor" href="#aio-capability-cloud-官方托管能力" aria-label="Permalink to &quot;AIO Capability Cloud：官方托管能力&quot;">​</a></h4><p>这是一个按需能力网络，不应和固定订阅无限绑定。</p><p>可逐步提供：</p><ul><li>官方模型 Gateway；</li><li>Web Search、网页抓取和公开网页蒸馏；</li><li>云端 OCR、转写、Embedding、Rerank；</li><li>高成本媒体生成；</li><li>Webhook 入口、定时触发和轻量后台任务；</li><li>桌面离线时可运行的少量纯云 Skill。</li></ul><p>这些服务有明显的可变成本，应使用独立的 <code>AIO Credits</code> 或按量账单。订阅可以赠送少量额度，但不能定义为无限使用。</p><p>官方模型的作用是：</p><ul><li>新用户免配置完成第一次 AI 操作；</li><li>给 Agent 和依赖 LLM 的工具提供可靠默认 Provider；</li><li>作为 BYOK、本地模型之外的可选后备；</li><li>支撑云端任务，而不是取代用户的模型配置。</li></ul><h4 id="aio-team-control-plane-管理多个用户和节点" tabindex="-1">AIO Team / Control Plane：管理多个用户和节点 <a class="header-anchor" href="#aio-team-control-plane-管理多个用户和节点" aria-label="Permalink to &quot;AIO Team / Control Plane：管理多个用户和节点&quot;">​</a></h4><p>后期高价值产品可能包括：</p><ul><li>团队成员、角色和设备节点；</li><li>共享 Agent、Skill、插件、工作流和 Knowledge；</li><li>统一 Provider、凭据代理和预算；</li><li>工具权限、自动审批政策和高风险操作审计；</li><li>私有插件/Skill Catalog；</li><li>远程节点健康、任务和版本管理；</li><li>SSO、数据保留、私有部署与支持。</li></ul><p>它卖的是治理和协作，不是更多 Chat 次数。</p><h3 id="_4-2-免费核心应该保持什么" tabindex="-1">4.2 免费核心应该保持什么 <a class="header-anchor" href="#_4-2-免费核心应该保持什么" aria-label="Permalink to &quot;4.2 免费核心应该保持什么&quot;">​</a></h3><p>AIO 的免费本地层应继续包含：</p><ul><li>不登录即可使用的工作区 Shell；</li><li>本地工具和本地文件处理；</li><li>BYOK、本地模型和用户自建 Provider；</li><li>本地 Asset、Knowledge、Recall、Agent 和项目；</li><li>本地安装的插件与 Skill；</li><li>手动配置的局域网、VPN 或自有隧道 Companion 路径；</li><li>数据导出、备份和迁移的基础能力。</li></ul><p>否则订阅会从“增强 Hub”变成“租用自己的本地工作环境”。</p><h3 id="_4-3-不建议收费或锁定的对象" tabindex="-1">4.3 不建议收费或锁定的对象 <a class="header-anchor" href="#_4-3-不建议收费或锁定的对象" aria-label="Permalink to &quot;4.3 不建议收费或锁定的对象&quot;">​</a></h3><ul><li>已经存在的本地工具；</li><li>BYOK 和本地模型；</li><li>用户自己的文件和资产访问；</li><li>基础插件 API、Tool Registry 和 Skill Runtime；</li><li>本地数据导出；</li><li>高风险操作的安全审批；</li><li>用户自己搭建的网络和 Provider。</li></ul><p>可以收费的是官方代运营、托管、连接、分发、协作和计算，而不是本地所有权。</p><h2 id="_5-推荐套餐结构" tabindex="-1">5. 推荐套餐结构 <a class="header-anchor" href="#_5-推荐套餐结构" aria-label="Permalink to &quot;5. 推荐套餐结构&quot;">​</a></h2><p>当前阶段不应立刻锁死价格，下面只作为产品实验假设。</p><h3 id="local-—-免费" tabindex="-1">Local — 免费 <a class="header-anchor" href="#local-—-免费" aria-label="Permalink to &quot;Local — 免费&quot;">​</a></h3><ul><li>完整本地 Hub；</li><li>BYOK / Local Model；</li><li>插件、Skill 和工具调用；</li><li>手动网络连接；</li><li>可获得一次性 AIO Capability Cloud 体验额度。</li></ul><h3 id="link-—-约-¥25–35-4–6-每月" tabindex="-1">Link — 约 ¥25–35 / $4–6 每月 <a class="header-anchor" href="#link-—-约-¥25–35-4–6-每月" aria-label="Permalink to &quot;Link — 约 ¥25–35 / $4–6 每月&quot;">​</a></h3><ul><li>3–5 台设备身份；</li><li>官方远程连接和 Relay；</li><li>任务与审批推送；</li><li>端到端加密的配置、Agent 和元数据备份；</li><li>有限备份空间和历史版本；</li><li>不包含大量模型成本。</li></ul><p>该价格需要按 Relay 带宽、存储、推送和支持的真实成本重新测算。</p><h3 id="plus-—-约-¥58–88-9–14-每月" tabindex="-1">Plus — 约 ¥58–88 / $9–14 每月 <a class="header-anchor" href="#plus-—-约-¥58–88-9–14-每月" aria-label="Permalink to &quot;Plus — 约 ¥58–88 / $9–14 每月&quot;">​</a></h3><ul><li>Link 全部能力；</li><li>更多设备、备份和历史；</li><li>Webhook、定时触发和托管轻量任务；</li><li>官方 Catalog、跨设备配置分发和高级恢复；</li><li>每月少量 AIO Credits；</li><li>可能包含官方签名能力包或高级工作流，但不应关闭开放生态。</li></ul><h3 id="compute-—-独立余额" tabindex="-1">Compute — 独立余额 <a class="header-anchor" href="#compute-—-独立余额" aria-label="Permalink to &quot;Compute — 独立余额&quot;">​</a></h3><ul><li>模型、搜索、OCR、转写、Embedding、图片和视频按量；</li><li>输入、输出、图片、秒数等价格透明；</li><li>用户可设置“订阅额度耗尽后停止”；</li><li>BYOK 使用不经过 AIO 计费。</li></ul><h3 id="team-—-席位-节点-用量" tabindex="-1">Team — 席位 + 节点 + 用量 <a class="header-anchor" href="#team-—-席位-节点-用量" aria-label="Permalink to &quot;Team — 席位 + 节点 + 用量&quot;">​</a></h3><ul><li>席位费承载权限、共享、审计和支持；</li><li>节点/Relay/存储按资源；</li><li>AI 和媒体计算按量；</li><li>私有部署单独报价。</li></ul><h2 id="_6-为什么不应先做模型月卡" tabindex="-1">6. 为什么不应先做模型月卡 <a class="header-anchor" href="#_6-为什么不应先做模型月卡" aria-label="Permalink to &quot;6. 为什么不应先做模型月卡&quot;">​</a></h2><h3 id="_6-1-它没有覆盖-aio-的核心网络效应" tabindex="-1">6.1 它没有覆盖 AIO 的核心网络效应 <a class="header-anchor" href="#_6-1-它没有覆盖-aio-的核心网络效应" aria-label="Permalink to &quot;6.1 它没有覆盖 AIO 的核心网络效应&quot;">​</a></h3><p>AIO 的复利来自：</p><ul><li>更多工具接入统一 Runtime；</li><li>更多工具可同时被人、Agent 和外部节点调用；</li><li>资产、知识、任务和结果在工具之间复用；</li><li>用户逐步构建自己的 Agent、Skill、工作流和能力环境。</li></ul><p>模型月卡只降低一次请求的配置门槛，不会自然增强这些复利。</p><h3 id="_6-2-当前产品还没有稳定的云服务对象" tabindex="-1">6.2 当前产品还没有稳定的云服务对象 <a class="header-anchor" href="#_6-2-当前产品还没有稳定的云服务对象" aria-label="Permalink to &quot;6.2 当前产品还没有稳定的云服务对象&quot;">​</a></h3><p>AIO 当前是 <code>0.7.0-alpha.1</code>，尚未发现成熟的：</p><ul><li>账号与设备身份；</li><li>支付和 Entitlement；</li><li>安全凭据存储；</li><li>Companion Gateway；</li><li>Relay、Push 和云备份；</li><li>线上 Catalog 和签名分发；</li><li>商业计量、退款和支持后台。</li></ul><p>此时直接增加模型套餐，最容易造出一个与本地 Hub 松散耦合的 API 中转业务。</p><h3 id="_6-3-开源桌面的付费价值必须在服务端成立" tabindex="-1">6.3 开源桌面的付费价值必须在服务端成立 <a class="header-anchor" href="#_6-3-开源桌面的付费价值必须在服务端成立" aria-label="Permalink to &quot;6.3 开源桌面的付费价值必须在服务端成立&quot;">​</a></h3><p>桌面端使用 Apache-2.0。纯客户端付费墙不可靠，也不符合当前开放定位。真正稳定的商业价值应来自用户无法通过删掉一个条件判断得到的服务：</p><ul><li>官方 Relay 和 Push；</li><li>加密云备份；</li><li>托管能力；</li><li>官方 Catalog、签名、扫描和更新；</li><li>团队控制面；</li><li>服务质量与支持。</li></ul><h2 id="_7-aio-cloud-的推荐架构" tabindex="-1">7. AIO Cloud 的推荐架构 <a class="header-anchor" href="#_7-aio-cloud-的推荐架构" aria-label="Permalink to &quot;7. AIO Cloud 的推荐架构&quot;">​</a></h2>`,94)),(a(),o(n,null,{default:l(()=>[r(i,{id:"mermaid-994",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Local%5B%22%E7%94%A8%E6%88%B7%E8%AE%BE%E5%A4%87%22%5D%0A%20%20%20%20%20%20%20%20DESK%5B%22AIO%20Desktop%5Cn%E6%9D%83%E5%A8%81%E7%8A%B6%E6%80%81%E4%B8%8E%E6%89%A7%E8%A1%8C%20Runtime%22%5D%0A%20%20%20%20%20%20%20%20MOB%5B%22AIO%20Mobile%5CnStandalone%20%2F%20Companion%20Client%22%5D%0A%20%20%20%20%20%20%20%20DESK%20--%3E%20TOOLS%5B%22Tools%20%2F%20Plugins%20%2F%20Skills%22%5D%0A%20%20%20%20%20%20%20%20DESK%20--%3E%20DATA%5B%22Assets%20%2F%20Knowledge%20%2F%20Recall%20%2F%20Projects%22%5D%0A%20%20%20%20%20%20%20%20DESK%20--%3E%20KEYS%5B%22%E7%94%A8%E6%88%B7%20Provider%20%E4%B8%8E%E6%9C%AC%E5%9C%B0%E5%AF%86%E9%92%A5%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Cloud%5B%22AIO%20Cloud%22%5D%0A%20%20%20%20%20%20%20%20ID%5B%22Account%20%2F%20Device%20Identity%22%5D%0A%20%20%20%20%20%20%20%20LINK%5B%22Signaling%20%2F%20Relay%20%2F%20Push%22%5D%0A%20%20%20%20%20%20%20%20BACKUP%5B%22Encrypted%20Backup%20Blob%22%5D%0A%20%20%20%20%20%20%20%20CAT%5B%22Plugin%20%2F%20Skill%20%2F%20Model%20Catalog%22%5D%0A%20%20%20%20%20%20%20%20ENT%5B%22Subscription%20%2F%20Entitlements%22%5D%0A%20%20%20%20%20%20%20%20BILL%5B%22Usage%20Ledger%22%5D%0A%20%20%20%20%20%20%20%20CAP%5B%22Optional%20Capability%20Gateway%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20MOB%20%3C--%3E%7C%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E5%8F%97%E6%8E%A7%20Companion%20%E5%8D%8F%E8%AE%AE%22%7C%20LINK%0A%20%20%20%20LINK%20%3C--%3E%7C%22%E5%8A%A0%E5%AF%86%20Relay%22%7C%20DESK%0A%20%20%20%20DESK%20--%3E%20ID%0A%20%20%20%20MOB%20--%3E%20ID%0A%20%20%20%20DESK%20--%3E%20BACKUP%0A%20%20%20%20CAT%20--%3E%20DESK%0A%20%20%20%20ENT%20--%3E%20LINK%0A%20%20%20%20ENT%20--%3E%20BACKUP%0A%20%20%20%20BILL%20--%3E%20CAP%0A%20%20%20%20DESK%20-.-%3E%7C%22%E7%94%A8%E6%88%B7%E9%80%89%E6%8B%A9%20AIO%20Cloud%20Provider%20%E6%97%B6%22%7C%20CAP%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t(`<h3 id="_7-1-cloud-是协调层-不是默认业务真源" tabindex="-1">7.1 Cloud 是协调层，不是默认业务真源 <a class="header-anchor" href="#_7-1-cloud-是协调层-不是默认业务真源" aria-label="Permalink to &quot;7.1 Cloud 是协调层，不是默认业务真源&quot;">​</a></h3><ul><li>设备、套餐、连接、Catalog 和账单由 Cloud 管理；</li><li>会话、项目、资产、密钥和工具状态默认仍由桌面管理；</li><li>Backup 保存加密快照或增量，不直接成为在线数据库；</li><li>Companion 命令由桌面验证并执行，Cloud Relay 不能绕过 scope 和审批。</li></ul><h3 id="_7-2-model-gateway-是独立-provider" tabindex="-1">7.2 Model Gateway 是独立 Provider <a class="header-anchor" href="#_7-2-model-gateway-是独立-provider" aria-label="Permalink to &quot;7.2 Model Gateway 是独立 Provider&quot;">​</a></h3><p>现有 <code>resolveModelExecution()</code> 和聚合渠道路由基础适合支持官方模型 Provider，但它应是 Capability Cloud 的一个模块：</p><ul><li><code>aio-cloud</code> 表示渠道身份；</li><li>Model Catalog 返回实际协议和能力；</li><li>客户端继续复用 OpenAI Responses、Anthropic、Gemini 等 adapter；</li><li>AIO Account 鉴权与静态 <code>apiKeys</code> 分离；</li><li>所有计量和限额服务端执行；</li><li>不向客户端下发共享上游 Key。</li></ul><h3 id="_7-3-catalog-不应变成封闭商店" tabindex="-1">7.3 Catalog 不应变成封闭商店 <a class="header-anchor" href="#_7-3-catalog-不应变成封闭商店" aria-label="Permalink to &quot;7.3 Catalog 不应变成封闭商店&quot;">​</a></h3><p>公共插件和 Skill 的发现、安装与基础更新应尽量开放。官方云服务可以提供：</p><ul><li>作者身份和包签名；</li><li>恶意行为/权限扫描；</li><li>平台产物自动验证；</li><li>兼容性矩阵与崩溃反馈；</li><li>私有 Catalog 和团队分发；</li><li>托管构建与发布；</li><li>付费能力包的许可证与分成。</li></ul><p>收费对象是信任、托管和私有分发，不是阻止用户加载本地插件。</p><h2 id="_8-分阶段落地" tabindex="-1">8. 分阶段落地 <a class="header-anchor" href="#_8-分阶段落地" aria-label="Permalink to &quot;8. 分阶段落地&quot;">​</a></h2><h3 id="phase-0-先固定产品边界" tabindex="-1">Phase 0：先固定产品边界 <a class="header-anchor" href="#phase-0-先固定产品边界" aria-label="Permalink to &quot;Phase 0：先固定产品边界&quot;">​</a></h3><p>在做支付前完成：</p><ol><li>明确 AIO Hub、AIO Link、AIO Capability Cloud、AIO Team 的边界；</li><li>明确 Local 模式在无账号、订阅过期和 Cloud 故障时仍然可用；</li><li>定义设备身份、权限 scope、远程任务和审计契约；</li><li>定义哪些数据可备份、哪些只可留在桌面、哪些可选择性发布；</li><li>建立插件/Skill/模型 Catalog 的统一身份和版本契约。</li></ol><h3 id="phase-1-账号、设备身份与加密备份" tabindex="-1">Phase 1：账号、设备身份与加密备份 <a class="header-anchor" href="#phase-1-账号、设备身份与加密备份" aria-label="Permalink to &quot;Phase 1：账号、设备身份与加密备份&quot;">​</a></h3><p>这是最小可收费服务的地基：</p><ul><li>Account 和 Device Session；</li><li>系统 Keychain/Credential Manager 安全存储；</li><li>设备配对、撤销和恢复；</li><li>加密配置/元数据备份；</li><li>真实的恢复演练；</li><li>Subscription/Entitlement 骨架，但先不公开收费。</li></ul><h3 id="phase-2-companion-gateway-与-link-内测" tabindex="-1">Phase 2：Companion Gateway 与 Link 内测 <a class="header-anchor" href="#phase-2-companion-gateway-与-link-内测" aria-label="Permalink to &quot;Phase 2：Companion Gateway 与 Link 内测&quot;">​</a></h3><ul><li>桌面 Companion Backend；</li><li>局域网和用户自有网络路径；</li><li>官方信令/Relay 作为独立 provider；</li><li>Push、任务恢复、事件 cursor；</li><li>权限 scope、高风险审批和审计；</li><li>邀请制验证 Relay 成本与远程使用频率。</li></ul><p>只有用户确实持续使用远程访问、推送和备份后，才正式上线 Link 订阅。</p><h3 id="phase-3-catalog-与跨设备能力分发" tabindex="-1">Phase 3：Catalog 与跨设备能力分发 <a class="header-anchor" href="#phase-3-catalog-与跨设备能力分发" aria-label="Permalink to &quot;Phase 3：Catalog 与跨设备能力分发&quot;">​</a></h3><ul><li>官方插件/Skill Catalog；</li><li>包签名、权限声明、平台产物检查；</li><li>自动更新与兼容提示；</li><li>Agent、Skill、模型预设的账号级备份和显式分发；</li><li>私有 Catalog 作为 Team 前置能力。</li></ul><h3 id="phase-4-capability-cloud" tabindex="-1">Phase 4：Capability Cloud <a class="header-anchor" href="#phase-4-capability-cloud" aria-label="Permalink to &quot;Phase 4：Capability Cloud&quot;">​</a></h3><ul><li>官方模型和低门槛体验；</li><li>Search、OCR、转写、Embedding 等托管能力；</li><li>Webhook、Scheduler 和少量云任务；</li><li>独立 Credits、计量、退款和风控；</li><li>明确国内/海外 Provider、数据和合规边界。</li></ul><h3 id="phase-5-team-enterprise" tabindex="-1">Phase 5：Team / Enterprise <a class="header-anchor" href="#phase-5-team-enterprise" aria-label="Permalink to &quot;Phase 5：Team / Enterprise&quot;">​</a></h3><ul><li>组织、席位、节点、预算和审计；</li><li>共享 Agent、Knowledge、Skill、插件和工作流；</li><li>Provider 凭据代理；</li><li>SSO、私有化、SLA 和支持。</li></ul><h2 id="_9-一个贫穷个人开发者能否负担-云服务成本估算" tabindex="-1">9. 一个贫穷个人开发者能否负担：云服务成本估算 <a class="header-anchor" href="#_9-一个贫穷个人开发者能否负担-云服务成本估算" aria-label="Permalink to &quot;9. 一个贫穷个人开发者能否负担：云服务成本估算&quot;">​</a></h2><h3 id="_9-1-估算口径" tabindex="-1">9.1 估算口径 <a class="header-anchor" href="#_9-1-估算口径" aria-label="Permalink to &quot;9.1 估算口径&quot;">​</a></h3><p>以下不是采购承诺，而是截至 <strong>2026-08-06</strong> 的公开标价快照，用来判断“这个可能性值不值得继续保留”。</p><ul><li>美元与人民币只按规划汇率 <code>1 USD ≈ ¥7.2</code> 粗算，不作为财务报价；</li><li>未含增值税、汇损、提现费、退款、拒付、人工支持、法律/隐私合规和安全事故成本；</li><li>未含模型、图片、视频、搜索等上游可变成本；这些必须由 Credits 或 BYOK 单独覆盖；</li><li>免费层只能用于验证，不应把“永久免费且永不改价”写进产品承诺；</li><li>最大不确定项不是数据库，而是 <strong>Relay 流量、支付费率和个人维护时间</strong>。</li></ul><h3 id="_9-2-一套便宜但不要求自建所有东西的价格锚点" tabindex="-1">9.2 一套便宜但不要求自建所有东西的价格锚点 <a class="header-anchor" href="#_9-2-一套便宜但不要求自建所有东西的价格锚点" aria-label="Permalink to &quot;9.2 一套便宜但不要求自建所有东西的价格锚点&quot;">​</a></h3><p>这不是最终选型，只是一套容易退出、适合小流量验证的成本基线。</p><table tabindex="0"><thead><tr><th>能力</th><th>可选服务与公开价格锚点</th><th>适合 AIO 的用法</th><th>主要风险</th></tr></thead><tbody><tr><td>API、Webhook、定时任务、轻量协调</td><td>Cloudflare Workers Free；Paid 最低 <code>$5/月</code>，含 <code>10M</code> 请求和 <code>30M</code> CPU ms</td><td>Account API 外围、支付 Webhook、Catalog、签名 URL、轻量信令</td><td>复杂状态和长任务不应全部塞进 Worker</td></tr><tr><td>Account、Postgres、管理后台地基</td><td>Supabase Free；Pro <code>$25/月</code>，含 <code>100k MAU</code>、<code>8GB</code> 数据库、<code>100GB</code> Storage、<code>250GB</code> Egress</td><td>先购买 Auth、DB、基础后台，不自己造完整身份系统</td><td>免费项目和正式 SLA 边界；供应商绑定；大陆网络质量</td></tr><tr><td>加密备份对象</td><td>Cloudflare R2 每月前 <code>10GB</code> 免费，之后标准存储 <code>$0.015/GB-month</code>；外网出口免费</td><td>只保存客户端加密后的快照、增量块和 manifest</td><td>请求次数、保留策略和误上传大资产仍会产生费用</td></tr><tr><td>Relay / TURN</td><td>Cloudflare Realtime TURN 每月前 <code>1,000GB</code> 免费，之后 <code>$0.05/GB</code>，按从 TURN 服务到客户端的出站流量计</td><td>NAT 穿透失败后的兜底；默认优先直连</td><td>大文件、桌面画面或持续媒体流会迅速把成本推高；不能据此承诺中国大陆体验</td></tr><tr><td>事务邮件</td><td>Resend Free <code>3,000 封/月</code>、<code>100 封/日</code>；Pro <code>$20/月</code>、<code>50,000 封/月</code></td><td>登录验证、设备通知、账单和安全邮件</td><td>免费层的每日上限很容易在登录异常时触发</td></tr><tr><td>Push、崩溃、远程开关</td><td>Firebase 的 Cloud Messaging、Crashlytics、Remote Config 等列为 no-cost 产品</td><td>移动 Push、崩溃聚合、云功能 kill switch</td><td>又增加一个供应商；SDK、隐私披露和地区可达性要单独验证</td></tr><tr><td>全球收款与税务代办</td><td>Paddle 标准公开价 <code>5% + $0.50/笔</code>，无月费；低于 <code>$10</code> 的产品可询问定制微支付费率</td><td>让 Merchant of Record 处理销售税/VAT、收据和订阅</td><td>低客单价固定手续费很伤；开户、提现地区和审核必须先确认</td></tr><tr><td>仅支付处理的对照</td><td>Stripe 美国线上银行卡标准价 <code>2.9% + $0.30/笔</code></td><td>在已有公司、税务和结算能力时比较</td><td>不是完整的全球税务代办；不能只比较表面费率</td></tr></tbody></table><p>如果只看服务器账单，一个 Hetzner CX23 公开起价约 <code>$6.49/月</code>，确实可以把 API、数据库甚至 coturn 都塞进一台机器。但这同时把补丁、备份、监控、入侵响应、单点故障和半夜恢复交给一个人。它适合实验或可随时丢弃的内测，不应因为“月租更低”就默认成为收费生产架构。</p><h3 id="_9-3-固定成本分阶段预算" tabindex="-1">9.3 固定成本分阶段预算 <a class="header-anchor" href="#_9-3-固定成本分阶段预算" aria-label="Permalink to &quot;9.3 固定成本分阶段预算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">建议直接现金上限</th><th>可以接受的形态</th><th>不应该做的事</th></tr></thead><tbody><tr><td>文档、等待名单、假门测试</td><td style="text-align:right;"><code>$0–5/月</code>（约 <code>¥0–36</code>）</td><td>免费层、静态页面、手工邀请、假 Entitlement</td><td>为没有用户的服务购买高可用、独立数据库和多区域</td></tr><tr><td>10–100 人邀请内测</td><td style="text-align:right;"><code>$5–30/月</code>（约 <code>¥36–216</code>）</td><td>Workers Paid + Supabase Free，或直接 Supabase Pro</td><td>自建支付、Kubernetes、多区域、全天候 Relay</td></tr><tr><td>出现真实付费用户</td><td style="text-align:right;"><code>$30–50/月</code>（约 <code>¥216–360</code>）</td><td>Workers Paid + Supabase Pro；邮件超过免费层再加 <code>$20</code></td><td>因为已有月费就提前承诺 SLA 或无限流量</td></tr><tr><td>iOS / Android 正式分发</td><td style="text-align:right;">iOS <code>$99/年</code>；Google Play <code>$25</code> 一次性注册费</td><td>作为渠道门票单列，不混进云账单</td><td>在未核对当期商店支付政策前设计客户端内购闭环</td></tr></tbody></table><p>建议给这个可能性设置硬预算闸门：</p><ol><li>没有预付费或明确愿付费用户前，固定云账单尽量不超过 <code>$10/月</code>；</li><li>第一批收费用户出现后，可以提高到 <code>$30–50/月</code>，但不要先买年付基础设施；</li><li>MRR 未超过 <code>$500</code> 前，固定基础设施尽量保持在 <code>$50/月</code> 内；</li><li>任何需要 <code>$100/月</code> 以上固定成本的设计，都必须先用真实用量证明必要性；</li><li>额度、预算和云功能必须有服务端 kill switch，不能依赖发新版客户端止血。</li></ol><h3 id="_9-4-存储很便宜-relay-才可能失控" tabindex="-1">9.4 存储很便宜，Relay 才可能失控 <a class="header-anchor" href="#_9-4-存储很便宜-relay-才可能失控" aria-label="Permalink to &quot;9.4 存储很便宜，Relay 才可能失控&quot;">​</a></h3><p>按 R2 当前标准存储价和 <code>10GB</code> 免费层估算，仅计算容量、不计算请求：</p><table tabindex="0"><thead><tr><th>假设</th><th style="text-align:right;">总存储</th><th style="text-align:right;">约月费</th></tr></thead><tbody><tr><td>100 用户，每人 <code>200MB</code> 加密备份</td><td style="text-align:right;"><code>20GB</code></td><td style="text-align:right;"><code>$0.15</code></td></tr><tr><td>1,000 用户，每人 <code>200MB</code></td><td style="text-align:right;"><code>200GB</code></td><td style="text-align:right;"><code>$2.85</code></td></tr><tr><td>1,000 用户，每人 <code>1GB</code></td><td style="text-align:right;"><code>1,000GB</code></td><td style="text-align:right;"><code>$14.85</code></td></tr></tbody></table><p>这说明配置、Agent、元数据和小型 Knowledge 索引的备份本身并不贵。真正危险的是把完整资产库、媒体缓存或历史生成文件默认同步上云。</p><p>按 Realtime TURN 的 <code>1TB/月</code> 免费层和超额 <code>$0.05/GB</code> 估算：</p><table tabindex="0"><thead><tr><th>假设</th><th style="text-align:right;">月 Relay 出站</th><th style="text-align:right;">约月费</th></tr></thead><tbody><tr><td>1,000 活跃用户，每人 <code>1GB</code></td><td style="text-align:right;"><code>1TB</code></td><td style="text-align:right;"><code>$0</code></td></tr><tr><td>1,000 活跃用户，每人 <code>5GB</code></td><td style="text-align:right;"><code>5TB</code></td><td style="text-align:right;"><code>$200</code></td></tr><tr><td>10,000 活跃用户，每人 <code>1GB</code></td><td style="text-align:right;"><code>10TB</code></td><td style="text-align:right;"><code>$450</code></td></tr></tbody></table><p>因此 Link 必须从一开始就限定产品边界：</p><ul><li>优先局域网、用户自有网络和端到端直连，Relay 只是失败回退；</li><li>Relay 默认传命令、小结果和必要元数据，不承诺远程桌面、视频流或无限文件中转；</li><li>大资产使用短期签名上传、明确额度或用户自有对象存储；</li><li>服务端记录每设备、每账号和每任务的字节数，并支持即时限流；</li><li>定价前至少邀请制测出“每周远程任务数、直连成功率、每用户 Relay GB”。</li></ul><h3 id="_9-5-低价月付的支付手续费比云账单更刺眼" tabindex="-1">9.5 低价月付的支付手续费比云账单更刺眼 <a class="header-anchor" href="#_9-5-低价月付的支付手续费比云账单更刺眼" aria-label="Permalink to &quot;9.5 低价月付的支付手续费比云账单更刺眼&quot;">​</a></h3><p>按 Paddle 标准 <code>5% + $0.50/笔</code> 粗算：</p><table tabindex="0"><thead><tr><th style="text-align:right;">客单价</th><th style="text-align:right;">单笔手续费</th><th style="text-align:right;">费率占比</th></tr></thead><tbody><tr><td style="text-align:right;"><code>$5/月</code></td><td style="text-align:right;"><code>$0.75</code></td><td style="text-align:right;"><code>15.0%</code></td></tr><tr><td style="text-align:right;"><code>$6/月</code></td><td style="text-align:right;"><code>$0.80</code></td><td style="text-align:right;"><code>13.3%</code></td></tr><tr><td style="text-align:right;"><code>$10/月</code></td><td style="text-align:right;"><code>$1.00</code></td><td style="text-align:right;"><code>10.0%</code></td></tr><tr><td style="text-align:right;"><code>$60/年</code></td><td style="text-align:right;"><code>$3.50</code></td><td style="text-align:right;"><code>5.8%</code></td></tr></tbody></table><p>这直接挑战前文 <code>Link $4–6/月</code> 的假设。对个人开发者，更现实的验证方式是：</p><ul><li>先做 <code>$48–60/年</code> 的创始用户年付，减少固定手续费和月度流失；</li><li>或把月付提高到能覆盖固定支付成本的价位，而不是靠“便宜”吸引没有强需求的用户；</li><li>如果一定要低于 <code>$10</code> 月付，先拿到微支付定制费率再公开价格；</li><li>不要为了省支付费率自己承担全球销售税、退款和订阅生命周期。</li></ul><p>一个简单情景：100 名用户按 <code>$5/月</code> 支付，月收入 <code>$500</code>；Paddle 标准手续费约 <code>$75</code>，再加 <code>$30</code> 固定云成本，尚未计算支持、退款、税务、上游计算和个人时间，直接现金支出已经约占收入 <code>21%</code>。如果同样 100 人改为 <code>$60/年</code>，折算月收入仍是 <code>$500</code>，支付手续费折算约 <code>$29.17/月</code>，加 <code>$30</code> 云成本约占 <code>11.8%</code>。</p><h3 id="_9-6-可复算的月成本公式" tabindex="-1">9.6 可复算的月成本公式 <a class="header-anchor" href="#_9-6-可复算的月成本公式" aria-label="Permalink to &quot;9.6 可复算的月成本公式&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月直接现金成本</span></span>
<span class="line"><span>  = 固定平台费</span></span>
<span class="line"><span>  + max(0, 备份 GB - 免费 GB) × 存储单价</span></span>
<span class="line"><span>  + max(0, Relay GB - 免费 GB) × Relay 单价</span></span>
<span class="line"><span>  + 邮件 / 日志 / 监控超额</span></span>
<span class="line"><span>  + 支付笔数 × 固定手续费</span></span>
<span class="line"><span>  + 收入 × 百分比手续费</span></span>
<span class="line"><span>  + 模型 / 搜索 / OCR / 媒体等上游成本</span></span>
<span class="line"><span>  + 退款、拒付与汇损</span></span></code></pre></div><p>Capability Cloud 不应使用“平均用户不会用很多”的无限套餐模型。最穷但最安全的做法仍是：<strong>BYOK 优先，官方能力预付费，余额不足即停，用户自行设置月预算。</strong></p><h3 id="_9-7-最低成本推荐-不是最低服务器价格推荐" tabindex="-1">9.7 最低成本推荐，不是最低服务器价格推荐 <a class="header-anchor" href="#_9-7-最低成本推荐-不是最低服务器价格推荐" aria-label="Permalink to &quot;9.7 最低成本推荐，不是最低服务器价格推荐&quot;">​</a></h3><p>如果只验证一个可能性，推荐顺序是：</p><ol><li><strong>先不做订阅</strong>：等待名单 + 手工邀请 + 本地功能；</li><li><strong>先验证 Backup，再验证 Link</strong>：Backup 的成本和协议边界更容易控制；</li><li><strong>使用托管 Auth/DB 和 MoR</strong>：多花几十美元，少承担最容易出事故的身份、税务和订阅状态机；</li><li><strong>Relay 只做限额回退</strong>：先测数据，不卖无限；</li><li><strong>不要同时做桌面、移动、模型 Gateway、Catalog 和 Team</strong>；</li><li>当付费用户证明价值后，再判断是否把托管服务迁到更便宜的自建组件。</li></ol><p>这里的“贫穷”不只指现金，也指注意力。个人开发者最稀缺的是能处理故障、退款、安全告警和平台审核的时间，而不是再写一个 CRUD 服务的能力。</p><h2 id="_10-应用客户端缺失的基础建设" tabindex="-1">10. 应用客户端缺失的基础建设 <a class="header-anchor" href="#_10-应用客户端缺失的基础建设" aria-label="Permalink to &quot;10. 应用客户端缺失的基础建设&quot;">​</a></h2><h3 id="_10-1-仓库里已经有的地基" tabindex="-1">10.1 仓库里已经有的地基 <a class="header-anchor" href="#_10-1-仓库里已经有的地基" aria-label="Permalink to &quot;10.1 仓库里已经有的地基&quot;">​</a></h3><p>客户端不是从零开始，以下能力可以复用或改造：</p><ul><li>桌面端已有 <a href="../../../src/services/app-updater.ts"><code>app-updater.ts</code></a>，支持 Tauri Updater 与 GitHub Release 检查；</li><li>桌面端已有较完整的 <a href="../../../src/composables/useDeepLinkHandler.ts"><code>useDeepLinkHandler.ts</code></a>，处理冷启动、热启动和多平台 Deep Link，并有敏感参数脱敏；</li><li>桌面和移动端都有 <code>createConfigManager</code>、模块 logger/error handler 和 Tauri HTTP 基础；</li><li>桌面端已有本地通知 store、启动管理、前端心跳/错误采集等本地运行基础；</li><li><code>web_distillery</code> 已实现面向 Cookie 的 Windows DPAPI、macOS Keychain、Linux libsecret/AES-GCM 加密，可作为跨平台实现经验参考；</li><li>移动端已有 <a href="../../../mobile/src/utils/http-client.ts"><code>http-client.ts</code></a> 的 Tauri HTTP、超时和取消封装。</li></ul><p>但这些还不是可收费云服务的客户端平台：</p><ul><li>当前 Deep Link 只处理 <code>add-profile</code>，而且历史协议允许 Key 出现在 URL 参数中；不能直接当 OAuth 回调实现；</li><li>通用 <code>ConfigManager</code> 写的是普通 JSON/YAML/JSONL 文件，不是安全凭据库；</li><li><code>web_distillery</code> 加密只服务于 Cookie，且不可用时允许明文 fallback，不能原样扩展为 Account refresh token 或设备私钥存储；</li><li>桌面端的 <a href="../../../src/utils/apiRequest.ts"><code>apiRequest.ts</code></a> 是 API Tester 的模板工具，不是带鉴权、重试和版本协商的 Cloud SDK；</li><li>移动端 <a href="../../../mobile/src/stores/user.ts"><code>user.ts</code></a> 只是把用户资料写入 <code>localStorage</code> 的占位状态，不构成真实登录会话；</li><li>移动端当前依赖中没有与桌面等价的 deep-link、updater、push 和安全凭据基础。</li></ul><h3 id="_10-2-缺口矩阵" tabindex="-1">10.2 缺口矩阵 <a class="header-anchor" href="#_10-2-缺口矩阵" aria-label="Permalink to &quot;10.2 缺口矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础能力</th><th>当前判断</th><th>最小可接受实现</th><th>为什么是收费前置</th></tr></thead><tbody><tr><td>Account 与 Session</td><td>桌面无统一 Account store/service；移动只有 localStorage 占位用户</td><td>OAuth/OIDC 或托管 Auth；PKCE；access token 短时化；refresh 单飞刷新；登出与全设备撤销</td><td>无法可靠区分用户、恢复会话或处理盗用</td></tr><tr><td>Device Identity</td><td>未发现安装身份、设备密钥、设备注册和撤销模型</td><td>每次安装生成设备 ID 与非导出私钥；设备名、平台、版本、最后在线；密钥轮换和撤销</td><td>Link、Backup 和审计都不能只信任账号 token</td></tr><tr><td>通用 Secret Vault</td><td>只有领域专用 Cookie 加密</td><td>Rust/Tauri 统一 <code>SecretStore</code>；Windows Credential/DPAPI、macOS Keychain、Linux Secret Service、移动 Keychain/Keystore；不可用时明确拒绝云登录或降级为临时会话</td><td>refresh token、设备私钥和恢复材料不能落普通配置文件</td></tr><tr><td>AIO Cloud SDK</td><td>只有分散 fetch/Tauri HTTP</td><td>统一 base URL、环境、鉴权头、超时、取消、指数退避、<code>Retry-After</code>、幂等键、request ID、客户端版本和协议版本</td><td>否则每个工具都会复制一套易错网络逻辑</td></tr><tr><td>Entitlement 客户端</td><td>不存在</td><td>服务端权威套餐；本地签名/缓存快照；过期时间、宽限期、刷新、降级和撤销；Local 功能永不被云故障锁死</td><td>不能靠前端布尔值或支付成功页面决定权限</td></tr><tr><td>Billing 入口</td><td>不存在</td><td>浏览器 Checkout、Billing Portal、回跳校验；客户端只展示服务端 entitlement，不接受价格或套餐参数作为事实</td><td>防止伪造套餐，处理退款、取消和 webhook 延迟</td></tr><tr><td>Auth Deep Link / Universal Link</td><td>桌面有协议基础，移动缺失</td><td><code>state</code>、<code>nonce</code>、PKCE verifier；一次性 code；禁止 token/key 出现在 URL；移动 App/Universal Link 与冷启动恢复</td><td>登录回调是最容易泄漏 token 和出现重放的入口之一</td></tr><tr><td>Encrypted Backup</td><td>只有 Recall 等领域本地备份，不是账号云备份</td><td>数据分类、schema version、manifest、客户端加密、分块、断点续传、完整性哈希、保留策略、恢复暂存区、真实恢复演练</td><td>“上传成功”不等于“能够恢复”；错误恢复会直接损坏用户数据</td></tr><tr><td>Outbox / Inbox 与离线恢复</td><td>未发现统一实现</td><td>本地持久队列、event cursor、幂等消费、重试上限、死信、冲突规则、网络状态机</td><td>桌面离线、进程退出和重复推送是常态</td></tr><tr><td>Companion 配对协议</td><td>仍是设计构想</td><td>二维码/短码配对、临时握手、设备公钥确认、scope、命令白名单、高风险审批、会话过期、直接/Relay 路径协商</td><td>不能把任意 Tauri command、文件路径或本地代理暴露给远端</td></tr><tr><td>Push</td><td>桌面只有应用内通知，移动无 Push 注册链路</td><td>APNs/FCM token 注册、轮换、失效清理、用户/设备路由、敏感内容最小化、点击恢复任务上下文</td><td>Companion 离开前台后需要可靠通知和审批入口</td></tr><tr><td>Feature Flag / Kill Switch</td><td>未发现统一云开关</td><td>服务端签名配置、缓存、默认安全值、分群、紧急关闭 Provider/Relay/上传</td><td>个人开发者无法保证随时发版和用户立即升级</td></tr><tr><td>可观测性与隐私</td><td>有本地 logger、错误处理和前端监控地基，无账号级云观测闭环</td><td>明确 opt-in；崩溃、请求失败率、版本、匿名安装 ID；日志脱敏；用户主动上传诊断包；删除与保留策略</td><td>没有数据无法支持远程故障，有过量数据又会制造隐私风险</td></tr><tr><td>Account / Device / Usage UI</td><td>不存在</td><td>登录态、设备列表与撤销、套餐、用量、预算、账单入口、备份状态、导出与删除账号</td><td>用户必须能理解并控制云端留下了什么</td></tr><tr><td>协议与最低版本治理</td><td>Updater 已有，但没有 Cloud 协议治理</td><td><code>clientVersion</code>、<code>protocolVersion</code>、最低支持版本、向后兼容窗口、软升级和紧急阻断</td><td>云端演进不能假设所有桌面客户端都已更新</td></tr><tr><td>测试与本地开发环境</td><td>没有 Cloud/Auth/Billing 一体化 fixture</td><td>mock server 或本地栈；过期 token、离线、重复 webhook、备份损坏、恢复回滚、Entitlement 宽限期、Relay 限额测试</td><td>这些状态无法靠“正常路径点一遍”验证</td></tr></tbody></table><h3 id="_10-3-首先要补的不是支付按钮" tabindex="-1">10.3 首先要补的不是支付按钮 <a class="header-anchor" href="#_10-3-首先要补的不是支付按钮" aria-label="Permalink to &quot;10.3 首先要补的不是支付按钮&quot;">​</a></h3><p>建议按以下横切层次建设，且每一层都可以在没有公开收费时独立验证。</p><h4 id="client-foundation-a-账号、设备和安全存储" tabindex="-1">Client Foundation A：账号、设备和安全存储 <a class="header-anchor" href="#client-foundation-a-账号、设备和安全存储" aria-label="Permalink to &quot;Client Foundation A：账号、设备和安全存储&quot;">​</a></h4><ul><li><code>AccountService</code> / <code>AccountStore</code>；</li><li><code>DeviceIdentityService</code>；</li><li>跨平台 <code>SecretStore</code>；</li><li><code>AioCloudClient</code>；</li><li>Auth callback 与会话恢复；</li><li>多环境配置，但生产 endpoint 不能被普通用户配置成任意地址后仍携带官方 token。</li></ul><p>这一层完成后，应用只获得“安全登录和识别设备”的能力，仍不应该收费。</p><h4 id="client-foundation-b-可恢复的数据产品" tabindex="-1">Client Foundation B：可恢复的数据产品 <a class="header-anchor" href="#client-foundation-b-可恢复的数据产品" aria-label="Permalink to &quot;Client Foundation B：可恢复的数据产品&quot;">​</a></h4><p>如果先做 Backup：</p><ul><li>定义可备份对象，不直接打包整个应用目录；</li><li>建立稳定导出格式、schema migration 和恢复事务；</li><li>客户端加密，服务端只看 blob、大小、版本和保留期；</li><li>至少完成 Windows 的上传—卸载/清空—恢复演练，再扩到 macOS/Linux；</li><li>移动端先作为查看状态和触发恢复的控制端，不强行同步所有桌面数据。</li></ul><p>Backup 比 Link 更适合第一个收费验证对象，因为成本可预测、威胁面更小，也能逼迫 AIO 先补齐数据可移植性。</p><h4 id="client-foundation-c-link-的异步与权限系统" tabindex="-1">Client Foundation C：Link 的异步与权限系统 <a class="header-anchor" href="#client-foundation-c-link-的异步与权限系统" aria-label="Permalink to &quot;Client Foundation C：Link 的异步与权限系统&quot;">​</a></h4><ul><li>持久 Outbox/Inbox 和任务 cursor；</li><li>设备配对、scope、审批和审计；</li><li>直连优先、Relay 回退；</li><li>Push 与任务恢复；</li><li>每账号/设备用量统计和限额；</li><li>紧急撤销设备、连接和云功能。</li></ul><p>Link 不是“加一个 WebSocket”，而是远程执行、安全、可靠性和生命周期管理的组合。</p><h4 id="client-foundation-d-entitlement-与商业生命周期" tabindex="-1">Client Foundation D：Entitlement 与商业生命周期 <a class="header-anchor" href="#client-foundation-d-entitlement-与商业生命周期" aria-label="Permalink to &quot;Client Foundation D：Entitlement 与商业生命周期&quot;">​</a></h4><p>最后再接：</p><ul><li>Checkout Session；</li><li>Webhook 驱动的服务端套餐状态；</li><li>客户端 Entitlement cache/grace；</li><li>Billing Portal；</li><li>取消、退款、拒付、过期、恢复订阅和账号删除；</li><li>Credits 账本、预算和用尽即停。</li></ul><p>支付成功回跳只负责提示刷新，不能直接把本地用户改成 Plus。</p><h3 id="_10-4-粗略工期-ai-能加速写代码-不能跳过平台验证" tabindex="-1">10.4 粗略工期：AI 能加速写代码，不能跳过平台验证 <a class="header-anchor" href="#_10-4-粗略工期-ai-能加速写代码-不能跳过平台验证" aria-label="Permalink to &quot;10.4 粗略工期：AI 能加速写代码，不能跳过平台验证&quot;">​</a></h3><p>以下是单人有效工作量的数量级，不是承诺排期；“人周”包括设计、实现、测试、恢复演练和文档，不只计算代码生成时间。</p><table tabindex="0"><thead><tr><th>可交付切片</th><th style="text-align:right;">粗略有效工作量</th><th>主要不可压缩项</th></tr></thead><tbody><tr><td>Account + Device + SecretStore + Cloud SDK</td><td style="text-align:right;"><code>3–6 人周</code></td><td>多平台安全存储、会话过期、Deep Link 冷/热启动</td></tr><tr><td>桌面端加密 Backup 可收费 MVP</td><td style="text-align:right;">再加 <code>5–9 人周</code></td><td>数据分类、迁移、分块、损坏恢复、真实恢复演练</td></tr><tr><td>Entitlement + Checkout + Portal + 基础运营后台</td><td style="text-align:right;">再加 <code>3–5 人周</code></td><td>webhook 状态机、退款/取消、宽限期、支持工具</td></tr><tr><td>Desktop ↔ Mobile Link MVP</td><td style="text-align:right;">再加 <code>8–14 人周</code></td><td>配对、Push、离线队列、权限、Relay、移动后台限制</td></tr><tr><td>可公开售卖且能独立维护的 Link</td><td style="text-align:right;">合计约 <code>20–34 人周</code></td><td>发布、观测、隐私、支持、故障演练和跨平台验收</td></tr></tbody></table><p>对业余时间个人开发者，这很容易展开成 <code>6–12 个月</code>，而不是“拼好几个 SDK 两周上线”。AI 可以显著减少模板代码和查文档时间，但不能替代支付账户审核、App Store/Play 审核、真机后台行为、密钥生命周期、恢复演练和线上支持。</p><h3 id="_10-5-推荐砍掉的范围" tabindex="-1">10.5 推荐砍掉的范围 <a class="header-anchor" href="#_10-5-推荐砍掉的范围" aria-label="Permalink to &quot;10.5 推荐砍掉的范围&quot;">​</a></h3><p>为了让这件事继续停留在“可研究的可能性”而不是吞掉主产品，第一轮明确不做：</p><ul><li>不同步完整 Chat、Knowledge、Asset 和插件运行态；</li><li>不做远程桌面、屏幕流、无限大文件 Relay；</li><li>不自建密码体系、全球税务、邮件投递和银行卡支付；</li><li>不做 Team、SSO、组织权限和私有部署；</li><li>不把模型套餐、Backup、Link、Catalog 同时公开；</li><li>不承诺中国大陆和海外同一套网络路径；</li><li>不让 Cloud 故障阻断 Local、BYOK、本地模型和本地插件；</li><li>不把 refresh token、设备私钥或恢复密钥写进 localStorage、普通 JSON 配置或 Deep Link。</li></ul><h3 id="_10-6-继续调查的最低触发条件" tabindex="-1">10.6 继续调查的最低触发条件 <a class="header-anchor" href="#_10-6-继续调查的最低触发条件" aria-label="Permalink to &quot;10.6 继续调查的最低触发条件&quot;">​</a></h3><p>只有出现以下信号，才值得从本文进入 architecture/plan：</p><ol><li>至少 <code>20</code> 名真实用户明确选择 Backup 或 Link，而不是笼统说“愿意支持”；</li><li>至少 <code>5–10</code> 人愿意预付创始年费或接受付费内测；</li><li>能用手工原型测出每用户备份 GB、每周远程任务数、直连成功率和 Relay GB；</li><li>支付/MoR 账户能够以当前个人或主体身份实际开户、收款和提现；</li><li>能接受先做桌面单端 Backup，不把移动 Companion 当作首发门槛；</li><li>有一份明确的云数据清单、威胁模型、删除/导出政策和每月预算上限。</li></ol><p>未达到这些条件时，最合理的结论不是“失败”，而是：<strong>保留产品边界和接口意识，不建设云服务。</strong></p><h2 id="_11-当前阶段的商业化建议" tabindex="-1">11. 当前阶段的商业化建议 <a class="header-anchor" href="#_11-当前阶段的商业化建议" aria-label="Permalink to &quot;11. 当前阶段的商业化建议&quot;">​</a></h2><p>本文应继续留在“可能性碎片”而不是产品路线图：<strong>不立项、不承诺日期、不提前购买长期基础设施，只保留边界、成本公式和验证触发条件。</strong></p><p>在 Link、Backup 或 Team Control Plane 尚未形成稳定价值前，<strong>不建议为了“别人都有订阅”而立即上线循环收费</strong>。</p><p>当前更合适的是：</p><ul><li>保持赞助/Supporter 计划；</li><li>用等待名单验证用户最愿意为什么付费：官方模型、远程访问、备份、移动 Companion、插件服务还是团队管理；</li><li>把账号和设备体系先作为未来服务基础，不在本地功能中制造付费墙；</li><li>若需要尽早测试模型服务，只做小范围欢迎额度或按量充值，不把它命名成 AIO 的核心订阅。</li></ul><p>真正适合 AIO 的订阅命题应当是：</p><blockquote><p><strong>让用户随时、安全、可靠地使用和扩展自己的 AIO Hub，而不是租用一个官方 Chat 入口。</strong></p></blockquote><h2 id="_12-验证指标" tabindex="-1">12. 验证指标 <a class="header-anchor" href="#_12-验证指标" aria-label="Permalink to &quot;12. 验证指标&quot;">​</a></h2><h3 id="link-companion" tabindex="-1">Link / Companion <a class="header-anchor" href="#link-companion" aria-label="Permalink to &quot;Link / Companion&quot;">​</a></h3><ul><li>已配对用户的周远程使用率；</li><li>远程任务完成率和恢复率；</li><li>p95 首次连接时间；</li><li>Relay 每活跃用户带宽和成本；</li><li>Push 打开率；</li><li>高风险审批响应与误触率。</li></ul><h3 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h3><ul><li>开启率；</li><li>每用户加密数据量；</li><li>真实恢复成功率；</li><li>版本回退使用率；</li><li>订阅取消后数据导出/清理成功率。</li></ul><h3 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h3><ul><li>插件/Skill 安装和留存；</li><li>自动更新成功率；</li><li>权限扫描和兼容性问题拦截量；</li><li>Agent 调用第三方能力的成功率；</li><li>私有 Catalog 的团队使用率。</li></ul><h3 id="capability-cloud" tabindex="-1">Capability Cloud <a class="header-anchor" href="#capability-cloud" aria-label="Permalink to &quot;Capability Cloud&quot;">​</a></h3><ul><li>没有 API Key 的首次成功率；</li><li>官方能力调用占 AIO 总任务的比例；</li><li>BYOK 与官方 Provider 的用户分层；</li><li>每项能力收入、成本和毛利；</li><li>Cloud 故障对 Local 模式的影响必须接近零。</li></ul><h2 id="_13-立即需要确认的产品原则" tabindex="-1">13. 立即需要确认的产品原则 <a class="header-anchor" href="#_13-立即需要确认的产品原则" aria-label="Permalink to &quot;13. 立即需要确认的产品原则&quot;">​</a></h2><ol><li>是否认可“AIO 是个人能力枢纽，Chat 是旗舰工作区而不是产品边界”；</li><li>是否承诺本地工具、BYOK、本地模型、插件 Runtime 和用户数据所有权长期不依赖订阅；</li><li>是否认可 Cloud 首要任务是连接和托管用户自己的 Hub，而不是接管桌面状态；</li><li>是否将官方模型作为可选 Capability Provider，而不是 AIO 订阅本体；</li><li>是否优先推进 Account/Device/Backup/Companion 契约，再讨论公开收费；</li><li>是否接受公开 Catalog 保持开放，收入主要来自托管、签名、私有分发、团队治理和云计算；</li><li>是否接受在没有预付费验证前把固定云预算锁在 <code>$10/月</code> 左右，并把首个产品收窄为 Backup 或 Link 二选一；</li><li>是否接受先补 Account、Device、SecretStore、Cloud SDK 和恢复演练，再接支付按钮。</li></ol><p>如果这些原则成立，下一份实施文档应聚焦：</p><blockquote><p><strong>AIO Account、Device Identity、SecretStore、Encrypted Backup 与 Companion Gateway 的产品/架构调查，并附带一个不超过 <code>$10/月</code> 的验证原型预算。</strong></p></blockquote><p>而不是直接编写模型订阅和 Token 账本施工计划。</p><h2 id="_14-仓库依据" tabindex="-1">14. 仓库依据 <a class="header-anchor" href="#_14-仓库依据" aria-label="Permalink to &quot;14. 仓库依据&quot;">​</a></h2><ul><li><a href="./../../architecture/overview"><code>AIO Hub 架构概览</code></a></li><li><a href="./../../architecture/tools-architecture-overview"><code>工具架构总集篇</code></a></li><li><a href="./../../architecture/services-architecture"><code>服务层架构</code></a></li><li><a href="./../../architecture/agent-tool-skill-integration"><code>Agent、工具调用与技能系统</code></a></li><li><a href="./../mobile-desktop-companion-connection-concept"><code>移动端作为桌面 Companion 的连接构想</code></a></li><li><a href="./../../guide/mobile-design-language"><code>移动端设计语言与产品定位决议</code></a></li><li><a href="./../../architecture/llm-execution-routing"><code>LLM 模型执行路由契约</code></a></li><li><a href="./../../guide/plugins/"><code>插件开发指南</code></a></li></ul><h2 id="_15-外部资料" tabindex="-1">15. 外部资料 <a class="header-anchor" href="#_15-外部资料" aria-label="Permalink to &quot;15. 外部资料&quot;">​</a></h2><p>价格与套餐页面访问日期：2026-08-06。价格会变动，进入实施前必须重新核对。</p><h3 id="_15-1-产品参照" tabindex="-1">15.1 产品参照 <a class="header-anchor" href="#_15-1-产品参照" aria-label="Permalink to &quot;15.1 产品参照&quot;">​</a></h3><ul><li><a href="https://manual.raycast.com/extensions" target="_blank" rel="noreferrer">Raycast Extensions</a></li><li><a href="https://manual.raycast.com/ai/ai-extensions" target="_blank" rel="noreferrer">Raycast AI Extensions</a></li><li><a href="https://www.raycast.com/pricing" target="_blank" rel="noreferrer">Raycast Pricing</a></li><li><a href="https://www.nabucasa.com/" target="_blank" rel="noreferrer">Home Assistant Cloud</a></li><li><a href="https://obsidian.md/pricing" target="_blank" rel="noreferrer">Obsidian Pricing</a></li><li><a href="https://msty.ai/pricing/" target="_blank" rel="noreferrer">Msty Pricing and Product Family</a></li><li><a href="https://n8n.io/pricing/" target="_blank" rel="noreferrer">n8n Pricing</a></li><li><a href="https://dify.ai/zh/pricing" target="_blank" rel="noreferrer">Dify Pricing</a></li><li><a href="https://chatboxai.app/zh-TW/guide/chatbox-ai/plans" target="_blank" rel="noreferrer">Chatbox AI Plans</a></li><li><a href="https://lobehub.com/pricing" target="_blank" rel="noreferrer">LobeHub Cloud Pricing</a></li></ul><h3 id="_15-2-成本与基础设施价格锚点" tabindex="-1">15.2 成本与基础设施价格锚点 <a class="header-anchor" href="#_15-2-成本与基础设施价格锚点" aria-label="Permalink to &quot;15.2 成本与基础设施价格锚点&quot;">​</a></h3><ul><li><a href="https://developers.cloudflare.com/workers/platform/pricing/" target="_blank" rel="noreferrer">Cloudflare Workers Pricing</a></li><li><a href="https://developers.cloudflare.com/r2/pricing/" target="_blank" rel="noreferrer">Cloudflare R2 Pricing</a></li><li><a href="https://developers.cloudflare.com/realtime/turn/pricing/" target="_blank" rel="noreferrer">Cloudflare Realtime TURN Pricing</a></li><li><a href="https://supabase.com/pricing" target="_blank" rel="noreferrer">Supabase Pricing</a></li><li><a href="https://www.paddle.com/pricing" target="_blank" rel="noreferrer">Paddle Pricing</a></li><li><a href="https://stripe.com/pricing" target="_blank" rel="noreferrer">Stripe Pricing</a></li><li><a href="https://resend.com/pricing" target="_blank" rel="noreferrer">Resend Pricing</a></li><li><a href="https://firebase.google.com/pricing" target="_blank" rel="noreferrer">Firebase Pricing</a></li><li><a href="https://www.hetzner.com/cloud/" target="_blank" rel="noreferrer">Hetzner Cloud</a></li><li><a href="https://developer.apple.com/help/account/membership/program-enrollment" target="_blank" rel="noreferrer">Apple Developer Program Enrollment</a></li><li><a href="https://support.google.com/googleplay/android-developer/answer/6112435" target="_blank" rel="noreferrer">Google Play Console Registration Fee</a></li></ul>`,122))])}const y=c(p,[["render",u]]);export{P as __pageData,y as default};
